import{_ as e,o as a,c as i,a0 as o}from"./chunks/framework.1R7PBCUH.js";const n="/computer-fundamentals/assets/vb_welcome.DPTJkyqe.png",s="/computer-fundamentals/assets/vb_configuration1.DXXPpJO6.png",r="/computer-fundamentals/assets/vb_configuration2.CjsiAIok.png",l="/computer-fundamentals/assets/vb_configuration3.Byc2I49S.png",u="/computer-fundamentals/assets/vb_settings1.Bbug2FmN.png",c="/computer-fundamentals/assets/vb_settings2.yWvtcIu4.png",d="/computer-fundamentals/assets/utm_welcome.z9GNhVgJ.png",h="/computer-fundamentals/assets/ubuntu_bootloader.Da365JjB.png",p="/computer-fundamentals/assets/vb_eject_disk.D692NAwr.png",m="/computer-fundamentals/assets/utm_eject_disk.zGgEVX-R.png",g="/computer-fundamentals/assets/ubuntu_login.xmV24PQx.png",b="/computer-fundamentals/assets/vb_guest_additions.B2wbwIU6.png",U=JSON.parse('{"title":"Setting Up a Virtual Machine","description":"","frontmatter":{},"headers":[],"relativePath":"labs/setting-up-a-vm.md","filePath":"labs/setting-up-a-vm.md"}'),f={name:"labs/setting-up-a-vm.md"};function y(v,t,k,w,x,_){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="setting-up-a-virtual-machine" tabindex="-1">Setting Up a Virtual Machine <a class="header-anchor" href="#setting-up-a-virtual-machine" aria-label="Permalink to &quot;Setting Up a Virtual Machine&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>This lab is still in draft. It contains all the information you need, but the text isn&#39;t polished yet.</p></div><p>In this lab, you&#39;ll prepare the virtual machine you need for these labs. You&#39;ll install a <strong>hypervisor</strong> that can create a virtual machine, and you&#39;ll install <strong>Ubuntu</strong> as the operating system for that virtual machine.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>To create your virtual machine, you need both a hypervisor and an Ubuntu installation disc suitable for your machine.</p><p>A <strong>hypervisor</strong> is software that creates and manages virtual machines. In this lab, you&#39;ll install a hypervisor that runs on top of your host operating system (Windows, macOS, or Linux). You&#39;ll install either <a href="https://www.virtualbox.org/wiki/Downloads" target="_blank" rel="noreferrer"><strong>VirtualBox</strong></a> or <a href="https://mac.getutm.app" target="_blank" rel="noreferrer"><strong>UTM</strong></a>.</p><p>The table below shows which hypervisor is recommended for your host operating system and CPU:</p><table tabindex="0"><thead><tr><th>Operating System</th><th>CPU</th><th>Hypervisor</th><th>Architecture</th></tr></thead><tbody><tr><td>Windows</td><td>AMD</td><td>VirtualBox</td><td>Intel / AMD 64-bit</td></tr><tr><td>Windows</td><td>Intel</td><td>VirtualBox</td><td>Intel / AMD 64-bit</td></tr><tr><td>Windows</td><td>Snapdragon</td><td>VirtualBox*</td><td>ARM 64-bit</td></tr><tr><td>macOS</td><td>Apple Silicon</td><td>UTM</td><td>ARM 64-bit</td></tr><tr><td>macOS</td><td>Intel</td><td>VirtualBox</td><td>Intel / AMD 64-bit</td></tr><tr><td>Linux</td><td>AMD</td><td>VirtualBox</td><td>Intel / AMD 64-bit</td></tr><tr><td>Linux</td><td>Intel</td><td>VirtualBox</td><td>Intel / AMD 64-bit</td></tr><tr><td>Linux</td><td>Snapdragon</td><td>VirtualBox*</td><td>ARM 64-bit</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">Note</p><p>Configurations with an asterisk (<code>*</code>) are experimental, as VirtualBox only has limited support for the ARM architecture. VirtualBox also has experimental support for Apple Silicon (M1, M2, …) but UTM performs much better on these machines.</p></div><p>The table also shows the <strong>architecture</strong> of your host machine. Ubuntu offers installation discs for both architectures. Pick the architecture that matches your host machine, or you won&#39;t be able to install Ubuntu on your virtual machine.</p><p>Download Ubuntu Desktop 26.04 LTS from <a href="https://ubuntu.com/download/desktop" target="_blank" rel="noreferrer">https://ubuntu.com/download/desktop</a>. You&#39;ll download an <strong>iso</strong> file that contains an exact copy of a physical installation disc. You&#39;ll use this file to install Ubuntu on your virtual machine. Wait for the file to download, then continue with the instructions for your hypervisor.</p><h2 id="creating-a-virtual-machine-in-virtualbox" tabindex="-1">Creating a virtual machine in VirtualBox <a class="header-anchor" href="#creating-a-virtual-machine-in-virtualbox" aria-label="Permalink to &quot;Creating a virtual machine in VirtualBox&quot;">​</a></h2><p>Download VirtualBox from <a href="https://www.virtualbox.org/wiki/Downloads" target="_blank" rel="noreferrer">https://www.virtualbox.org/wiki/Downloads</a> and install it.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>If you&#39;re already running Linux (which is awesome, by the way), it may be easier to install VirtualBox through your distribution&#39;s package manager. If you&#39;re taking that route, also install the VirtualBox Guest Additions, as you&#39;ll need those later.</p></div><p>When you first launch VirtualBox, you&#39;ll see the following screen:</p><p><img src="'+n+'" alt="VirtualBox welcome screen"></p><p>Select “Expert Mode”, then click “New” to create a virtual machine.</p><p>For the “ISO Image”, select the file you downloaded earlier. Uncheck “Proceed with Unattended Installation” and select “Linux” as the operating system, “Ubuntu” as the distribution, and “Ubuntu (64 bit)” as the version:</p><p><img src="'+s+'" alt="VirtualBox configuration"></p><p>Under “Specify virtual hardware”, allocate at least 4096MB of RAM and two CPU cores:</p><p><img src="'+r+'" alt="VirtualBox configuration"></p><p>Under “Specify virtual hard disk”, select “Create a New Virtual Hard Disk” and allocate at least 64GB of storage:</p><p><img src="'+l+'" alt="VirtualBox configuration"></p><p>Create your virtual machine, but don&#39;t start it yet.</p><p>Click “Settings”, go to “Display” and maximize the “Video Memory”:</p><p><img src="'+u+'" alt="VirtualBox display settings"></p><p>Go to “Storage” and verify that the installation disc is inserted and that you have a virtual hard disk:</p><p><img src="'+c+'" alt="VirtualBox storage settings"></p><p>Save your settings, then start the virtual machine.</p><h2 id="creating-a-virtual-machine-in-utm" tabindex="-1">Creating a virtual machine in UTM <a class="header-anchor" href="#creating-a-virtual-machine-in-utm" aria-label="Permalink to &quot;Creating a virtual machine in UTM&quot;">​</a></h2><p>Download UTM from <a href="https://mac.getutm.app" target="_blank" rel="noreferrer">https://mac.getutm.app</a> and install it into the <strong>Applications</strong> directory.</p><p>When you first launch UTM, you&#39;ll see the following screen:</p><p><img src="'+d+'" alt="UTM welcome screen"></p><p>Select “Create a New Virtual Machine” and create a virtual machine with the following configuration:</p><ul><li>Select “Virtualize”, not “Emulate”.</li><li>Select “Linux” as the guest operating system.</li><li>Allocate at least 4096MB of RAM and two CPU cores.</li><li>For the &quot;Boot Image Type&quot;, select “Boot from ISO image”, then click “Browse” and select the file you downloaded earlier.</li><li>Allocate at least 64GB of storage.</li><li>A shared directory is optional; you don&#39;t need one for this course.</li></ul><p>Save your configuration, then start the virtual machine.</p><h2 id="installing-ubuntu" tabindex="-1">Installing Ubuntu <a class="header-anchor" href="#installing-ubuntu" aria-label="Permalink to &quot;Installing Ubuntu&quot;">​</a></h2><p>If your virtual machine was configured correctly, it should boot from the installation disc and show the following screen:</p><p><img src="'+h+'" alt="Bootloader screen"></p><p>Select “Try or Install Ubuntu”.</p><p>The Ubuntu installation process is fairly straightforward. You&#39;ll be asked to select your language, choose a keyboard layout, set your time zone, create a user account, and so on.</p><p>Pay extra attention to the following steps:</p><ul><li>Select “Use wired connection” to connect to the internet. Your hypervisor will provide this connection to the virtual machine.</li><li>Select “Install Ubuntu”, not “Try Ubuntu”.</li><li>Select “Interactive installation”.</li><li>When asked what apps you would like to install, either option is fine. The “Default selection” contains everything you need for this course, but the “Extended selection” gives you a richer experience.</li><li>No proprietary software is required for this course, but you may want to install support for additional media formats.</li><li>Select “Erase disk and install Ubuntu”. That sounds scary, but it only erases your virtual hard disk, not your actual one.</li></ul><p>When the installation completes, you&#39;ll be asked to restart your virtual machine. As the machine reboots, you have to remove the installation disc or you&#39;ll end up back in the Ubuntu installer.</p><p>In VirtualBox, click the CD icon in the bottom tray:</p><p><img src="'+p+'" alt="Ejecting the installation disc in VirtualBox"></p><p>In UTM, click the CD icon in the toolbar:</p><p><img src="'+m+'" alt="Ejecting the installation disc in UTM"></p><p>From there, you can eject the installation disc.</p><p>You&#39;ll know the installation was succesful when Ubuntu prompts you to sign in with the account you created during installation:</p><p><img src="'+g+`" alt="Ubuntu login screen"></p><p>After signing in, click your way through the final setup screens, and you&#39;re ready to use Ubuntu!</p><h2 id="additional-configuration-for-virtualbox" tabindex="-1">Additional configuration for VirtualBox <a class="header-anchor" href="#additional-configuration-for-virtualbox" aria-label="Permalink to &quot;Additional configuration for VirtualBox&quot;">​</a></h2><p>If you&#39;re using VirtualBox, I highly recommend that you install the Guest Additions in your virtual machine. These additions add support for drag and drop, shared folders, and a shared clipboard, and provide overall better performance.</p><p>First, install some required software from the command line. Press the <code>Windows</code> or <code>Command</code> key, type “terminal” to search for the Terminal application, and open it.</p><p>Run the following commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build-essential</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dkms</span></span></code></pre></div><p>Press <code>Enter</code> after each command and follow the on-screen instructions. When you&#39;re done, close Terminal.</p><div class="info custom-block"><p class="custom-block-title">Note</p><p>You&#39;ll learn to use the command line in the next lab, and you&#39;ll learn more about installing software in <a href="./package-management.html">Package Management</a>.</p></div><p>Select “Devices” ▸ “Insert Guest Additions CD image...” from the menu bar. This will attach the Guest Additions CD as a virtual disc, which should show up in the sidebar of the Files application:</p><p><img src="`+b+'" alt="Guest Additions CD"></p><p>Click “Run Software” to install the Guest Additions and restart the virtual machine when you&#39;re done.</p><h2 id="up-next" tabindex="-1">Up next <a class="header-anchor" href="#up-next" aria-label="Permalink to &quot;Up next&quot;">​</a></h2><p>In the next lab, you&#39;ll explore Ubuntu and learn to use both the graphical user interface and the command line.</p>',64)])])}const V=e(f,[["render",y]]);export{U as __pageData,V as default};
